 const { useState } = React;

 const Checkbox = ({ id, name, value, label, checked, onChange }) => (
   <div className="checkbox-wrapper">
     <input
       type="checkbox"
       id={id}
       name={name}
       value={value}
       checked={checked}
       onChange={onChange}
     />
     <label htmlFor={id}>{label}</label>
   </div>
 );

 const QuizQuestion = ({ id, question, helpText, errorText, options, selectedValues, onOptionChange }) => {
   const helpId = helpText ? `${id}-help` : null;
   const errorId = errorText ? `${id}-error` : null;
   const describedBy = [helpId, errorId].filter(Boolean).join(" ");

   return (
     <div className="form-field">
       <fieldset aria-describedby={describedBy || undefined}>
         <legend>
           {question}
           <span className="required-marker" aria-hidden="true">*</span>
         </legend>
         {helpText && <p id={helpId} className="help-text">{helpText}</p>}
         {errorText && <p id={errorId} className="error-text">Error: {errorText}</p>}
         <div className="options-group">
           {options.map((option) => (
             <Checkbox
               key={option.value}
               id={`${id}-${option.value}`}
               name={id}
               value={option.value}
               label={option.label}
               checked={selectedValues.includes(option.value)}
               onChange={() => onOptionChange(option.value)}
             />
           ))}
         </div>
       </fieldset>
     </div>
   );
 };

 const App = () => {
   const [selections, setSelections] = useState({
     q1: [],
     q2: [],
     q3: []
   });
   const [submitted, setSubmitted] = useState(false);

   const questions = [
     {
       id: "q1",
       question: "Which of these are statically typed languages?",
       helpText: "Select all that apply. Statically typed languages check types at compile-time.",
       options: [
         { label: "Python", value: "python" },
         { label: "TypeScript", value: "typescript" },
         { label: "Java", value: "java" },
         { label: "Ruby", value: "ruby" }
       ]
     },
     {
       id: "q2",
       question: "Which languages were created before 1995?",
       options: [
         { label: "C (1972)", value: "c" },
         { label: "C++ (1985)", value: "cpp" },
         { label: "JavaScript (1995)", value: "js" },
         { label: "PHP (1994)", value: "php" }
       ]
     },
     {
       id: "q3",
       question: "Which of these are commonly used for web development?",
       options: [
         { label: "HTML", value: "html" },
         { label: "CSS", value: "css" },
         { label: "JavaScript", value: "js" },
         { label: "SQL", value: "sql" }
       ]
     }
   ];

   const handleOptionChange = (questionId, value) => {
     setSelections(prev => {
       const current = prev[questionId];
       const next = current.includes(value)
         ? current.filter(v => v !== value)
         : [...current, value];
       return { ...prev, [questionId]: next };
     });
   };

   const isFormValid = selections.q1.length > 0 && selections.q2.length > 0 && selections.q3.length > 0;

   const handleSubmit = (e) => {
     e.preventDefault();
     if (isFormValid) {
       setSubmitted(true);
     } else {
       // Focus first field with error
       if (selections.q1.length === 0) {
         document.getElementById('q1-python').focus();
       } else if (selections.q2.length === 0) {
         document.getElementById('q2-c').focus();
       } else if (selections.q3.length === 0) {
         document.getElementById('q3-html').focus();
       }
     }
   };

   return (
     <main>
       <h1>Computer Languages Quiz</h1>
       <form onSubmit={handleSubmit} noValidate>
         {questions.map((q) => (
           <QuizQuestion
             key={q.id}
             id={q.id}
             question={q.question}
             helpText={q.helpText}
             errorText={submitted ? null : (selections[q.id].length === 0 ? "Please select at least one option." : null)}
             options={q.options}
             selectedValues={selections[q.id]}
             onOptionChange={(value) => handleOptionChange(q.id, value)}
           />
         ))}
         <button type="submit">Submit Quiz</button>
       </form>

       {submitted && (
         <section className="results" aria-live="polite">
           <h2>Quiz Submitted!</h2>
           <p>Thank you for participating. Your selections have been recorded.</p>
           <ul>
             {questions.map(q => (
               <li key={q.id}>
                 <strong>{q.question}</strong>: {selections[q.id].length > 0 ? selections[q.id].join(", ") : "None selected"}
               </li>
             ))}
           </ul>
         </section>
       )}
     </main>
   );
 };

 const root = ReactDOM.createRoot(document.getElementById('root'));
 root.render(<App />);

